import fs from "node:fs";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
const TOKEN_FILE = "<scratch>";
const token = JSON.parse(fs.readFileSync(TOKEN_FILE, "utf8")).token;
const [tool, argsJson] = process.argv.slice(2);
const transport = new StreamableHTTPClientTransport(new URL("http://192.168.31.145:8799/mcp"), {
  requestInit: { headers: { Authorization: `Bearer ${token}` } },
});
const client = new Client({ name: "trial10-ana", version: "1.0.0" });
await client.connect(transport);
const call = async (name, args) => {
  const r = await client.callTool({ name, arguments: args });
  return (r.content || []).map((c) => c.text ?? JSON.stringify(c)).join("\n");
};
try {
  if (tool === "--list") {
    const r = await client.listTools();
    console.log(r.tools.map((t) => t.name).join("\n"));
  } else {
    let args = argsJson ? JSON.parse(argsJson) : {};
    if (JSON.stringify(args).includes("$MANDATE")) {
      const w = JSON.parse(await call("whoami", {}));
      args = JSON.parse(JSON.stringify(args).replaceAll("$MANDATE", w.ap2.openPaymentMandate));
    }
    console.log(await call(tool, args));
  }
} finally {
  await client.close();
}
EOF
